import 'package:flutter/material.dart';import '../../transfers/presentation/transfer_intelligence_screen.dart';import '../../social/presentation/friend_activity_screen.dart';import '../../predictions/presentation/prediction_seasons_screen.dart';
class V07HubScreen extends StatelessWidget{const V07HubScreen({super.key});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Global V0.7 Hub')),body:ListView(padding:const EdgeInsets.all(12),children:[_tile(context,'Transfer Intelligence',Icons.swap_horiz,const TransferIntelligenceScreen()),_tile(context,'Friends Activity',Icons.people_alt_outlined,FriendActivityScreen()),_tile(context,'Prediction Seasons',Icons.emoji_events_outlined,PredictionSeasonsScreen())]));Widget _tile(BuildContext c,String t,IconData i,Widget page)=>Card(child:ListTile(leading:Icon(i),title:Text(t),trailing:const Icon(Icons.chevron_right),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>page))));}
